# Put the person on hold, or take them off hold when already held.
validate:
  class: net.officefloor.hq.app.person.ValidateHold
  next: snapshot
# The sheet's figures before the change, so the change can audit what it moved.
snapshot:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  govern: [ transaction ]
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: hold
hold:
  class: net.officefloor.hq.app.person.HoldPerson
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithPerson
  govern: [ transaction ]
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateHold {
    public void validate(@RequestBody HoldRequest request, Out<HoldRequest> body) {
        body.set(request);
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupFigures;
import net.officefloor.plugin.variable.Val;

/** Puts the person on hold, or releases them when already held. While held their OPEN claims count
 *  in no live total; their SETTLED claims still do. */
public class HoldPerson {
    public void hold(@Val HoldRequest request, @Val Person person, People people, Audit audit,
            @Val RollupFigures before, Rollup rollup) {
        person.setHeld(!person.isHeld());
        people.saveHeld(person);
        audit.recordOnCommit((person.isHeld() ? "PERSON_HELD" : "PERSON_RELEASED") + " sheet=" + person.getSheetId()
                + " by=" + request.user() + " name=" + person.getName());
        rollup.recordChanges(person.getSheetId(), request.user(), before);
    }
}
package net.officefloor.hq.app.person;

/** Body of POST /api/sheets/{sheetId}/people/{personId}/hold: who holds (or releases) them. */
